/*
 * The carried TweetNaCl gives the published answers: the key agreement of RFC 7748, NaCl's own
 * test of a box (as libsodium 1.0.18 carries it, test/default/box.c and box.exp), the first
 * signature test of RFC 8032, and SHA-512 of "abc". This is gosh's file; tweetnacl.c and
 * tweetnacl.h beside it are not.
 */
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include "tweetnacl.h"

/* NaCl's own box test (libsodium 1.0.18, test/default/box.c and box.exp): inputs and the expected sealed bytes. */
static const unsigned char BOX_ALICE_SK[32] = { 0x77, 0x07, 0x6d, 0x0a, 0x73, 0x18, 0xa5, 0x7d, 0x3c, 0x16, 0xc1, 0x72, 0x51, 0xb2, 0x66, 0x45, 0xdf, 0x4c, 0x2f, 0x87, 0xeb, 0xc0, 0x99, 0x2a, 0xb1, 0x77, 0xfb, 0xa5, 0x1d, 0xb9, 0x2c, 0x2a };
static const unsigned char BOX_BOB_PK[32] = { 0xde, 0x9e, 0xdb, 0x7d, 0x7b, 0x7d, 0xc1, 0xb4, 0xd3, 0x5b, 0x61, 0xc2, 0xec, 0xe4, 0x35, 0x37, 0x3f, 0x83, 0x43, 0xc8, 0x5b, 0x78, 0x67, 0x4d, 0xad, 0xfc, 0x7e, 0x14, 0x6f, 0x88, 0x2b, 0x4f };
static const unsigned char BOX_NONCE[24] = { 0x69, 0x69, 0x6e, 0xe9, 0x55, 0xb6, 0x2b, 0x73, 0xcd, 0x62, 0xbd, 0xa8, 0x75, 0xfc, 0x73, 0xd6, 0x82, 0x19, 0xe0, 0x03, 0x6b, 0x7a, 0x0b, 0x37 };
static const unsigned char BOX_MESSAGE[131] = { 0xbe, 0x07, 0x5f, 0xc5, 0x3c, 0x81, 0xf2, 0xd5, 0xcf, 0x14, 0x13, 0x16, 0xeb, 0xeb, 0x0c, 0x7b, 0x52, 0x28, 0xc5, 0x2a, 0x4c, 0x62, 0xcb, 0xd4, 0x4b, 0x66, 0x84, 0x9b, 0x64, 0x24, 0x4f, 0xfc, 0xe5, 0xec, 0xba, 0xaf, 0x33, 0xbd, 0x75, 0x1a, 0x1a, 0xc7, 0x28, 0xd4, 0x5e, 0x6c, 0x61, 0x29, 0x6c, 0xdc, 0x3c, 0x01, 0x23, 0x35, 0x61, 0xf4, 0x1d, 0xb6, 0x6c, 0xce, 0x31, 0x4a, 0xdb, 0x31, 0x0e, 0x3b, 0xe8, 0x25, 0x0c, 0x46, 0xf0, 0x6d, 0xce, 0xea, 0x3a, 0x7f, 0xa1, 0x34, 0x80, 0x57, 0xe2, 0xf6, 0x55, 0x6a, 0xd6, 0xb1, 0x31, 0x8a, 0x02, 0x4a, 0x83, 0x8f, 0x21, 0xaf, 0x1f, 0xde, 0x04, 0x89, 0x77, 0xeb, 0x48, 0xf5, 0x9f, 0xfd, 0x49, 0x24, 0xca, 0x1c, 0x60, 0x90, 0x2e, 0x52, 0xf0, 0xa0, 0x89, 0xbc, 0x76, 0x89, 0x70, 0x40, 0xe0, 0x82, 0xf9, 0x37, 0x76, 0x38, 0x48, 0x64, 0x5e, 0x07, 0x05 };
static const unsigned char BOX_SEALED[147] = { 0xf3, 0xff, 0xc7, 0x70, 0x3f, 0x94, 0x00, 0xe5, 0x2a, 0x7d, 0xfb, 0x4b, 0x3d, 0x33, 0x05, 0xd9, 0x8e, 0x99, 0x3b, 0x9f, 0x48, 0x68, 0x12, 0x73, 0xc2, 0x96, 0x50, 0xba, 0x32, 0xfc, 0x76, 0xce, 0x48, 0x33, 0x2e, 0xa7, 0x16, 0x4d, 0x96, 0xa4, 0x47, 0x6f, 0xb8, 0xc5, 0x31, 0xa1, 0x18, 0x6a, 0xc0, 0xdf, 0xc1, 0x7c, 0x98, 0xdc, 0xe8, 0x7b, 0x4d, 0xa7, 0xf0, 0x11, 0xec, 0x48, 0xc9, 0x72, 0x71, 0xd2, 0xc2, 0x0f, 0x9b, 0x92, 0x8f, 0xe2, 0x27, 0x0d, 0x6f, 0xb8, 0x63, 0xd5, 0x17, 0x38, 0xb4, 0x8e, 0xee, 0xe3, 0x14, 0xa7, 0xcc, 0x8a, 0xb9, 0x32, 0x16, 0x45, 0x48, 0xe5, 0x26, 0xae, 0x90, 0x22, 0x43, 0x68, 0x51, 0x7a, 0xcf, 0xea, 0xbd, 0x6b, 0xb3, 0x73, 0x2b, 0xc0, 0xe9, 0xda, 0x99, 0x83, 0x2b, 0x61, 0xca, 0x01, 0xb6, 0xde, 0x56, 0x24, 0x4a, 0x9e, 0x88, 0xd5, 0xf9, 0xb3, 0x79, 0x73, 0xf6, 0x22, 0xa4, 0x3d, 0x14, 0xa6, 0x59, 0x9b, 0x1f, 0x65, 0x4c, 0xb4, 0x5a, 0x74, 0xe3, 0x55, 0xa5 };
/* (TweetNaCl asks its user for random bytes, to make keys. Nothing here makes one.) */
void randombytes(unsigned char* b, unsigned long long n) { (void)b; (void)n; abort(); }
static int fails = 0;
static void hex(const char* h, unsigned char* out) { for (size_t i = 0; h[2*i]; i++) { unsigned v; sscanf(h + 2*i, "%2x", &v); out[i] = v; } }
static void check(const char* what, int ok) { printf("%-70s %s\n", what, ok ? "ok" : "FAIL"); fails += !ok; }
int main(void) {
  unsigned char a_sk[32], a_pk[32], b_sk[32], b_pk[32], want[64], got[64], k1[32], k2[32];
  hex("77076d0a7318a57d3c16c17251b26645df4c2f87ebc0992ab177fba51db92c2a", a_sk);
  hex("5dab087e624a8a4b79e17f8b83800ee66f3bb1292618b6fd1c2f8b27ff88e0eb", b_sk);
  crypto_scalarmult_base(a_pk, a_sk); crypto_scalarmult_base(b_pk, b_sk);
  hex("8520f0098930a754748b7ddcb43ef75a0dbf3a0d26381af4eba4a98eaa9b4e6a", want); check("X25519, RFC 7748: Alice's public key", !memcmp(a_pk, want, 32));
  hex("de9edb7d7b7dc1b4d35b61c2ece435373f8343c85b78674dadfc7e146f882b4f", want); check("X25519, RFC 7748: Bob's public key", !memcmp(b_pk, want, 32));
  crypto_scalarmult(k1, a_sk, b_pk); crypto_scalarmult(k2, b_sk, a_pk);
  hex("4a5d9d5ba4ce2de1728e3bf480350f25e07e21c947d19e3376f09b3c1e161742", want); check("X25519, RFC 7748: the shared secret, from both sides", !memcmp(k1, want, 32) && !memcmp(k2, want, 32));

  unsigned char m[163] = {0}, c[163], back[163];
  memcpy(m + 32, BOX_MESSAGE, 131);
  check("box: seals", crypto_box(c, m, 163, BOX_NONCE, BOX_BOB_PK, BOX_ALICE_SK) == 0);
  check("box, NaCl's own test: the sealed bytes are as published", !memcmp(c + 16, BOX_SEALED, 147));
  check("box: Bob opens what Alice sealed", crypto_box_open(back, c, 163, BOX_NONCE, a_pk, b_sk) == 0 && !memcmp(back + 32, BOX_MESSAGE, 131));
  c[40] ^= 1; check("box: one bit changed, it does not open", crypto_box_open(back, c, 163, BOX_NONCE, a_pk, b_sk) != 0);

  unsigned char sk[64], pk[32], sm[64 + 8], opened[64 + 8]; unsigned long long smlen, mlen;
  hex("9d61b19deffd5a60ba844af492ec2cc44449c5697b326919703bac031cae7f60", sk);
  hex("d75a980182b10ab7d54bfed3c964073a0ee172f3daa62325af021a68f707511a", pk); memcpy(sk + 32, pk, 32);
  crypto_sign(sm, &smlen, (const unsigned char*)"", 0, sk);
  hex("e5564300c360ac729086e2cc806e828a84877f1eb8e5d974d873e06522490155"
      "5fb8821590a33bacc61e39701cf9b46bd25bf5f0595bbe24655141438e7a100b", want);
  check("Ed25519, RFC 8032 test 1: the signature of nothing", smlen == 64 && !memcmp(sm, want, 64));
  check("Ed25519: it verifies", crypto_sign_open(opened, &mlen, sm, smlen, pk) == 0 && mlen == 0);
  sm[3] ^= 1; check("Ed25519: one bit changed, it does not", crypto_sign_open(opened, &mlen, sm, smlen, pk) != 0);

  crypto_hash(got, (const unsigned char*)"abc", 3);
  hex("ddaf35a193617abacc417349ae20413112e6fa4e89a97ea20a9eeee64b55d39a"
      "2192992a274fc1a836ba3c23a3feebbd454d4423643ce80e2a9ac94fa54ca49f", want);
  check("SHA-512 of \"abc\"", !memcmp(got, want, 64));
  printf(fails ? "FAIL: TweetNaCl does not give the published answers\n" : "PASS: TweetNaCl gives the published answers\n");
  return fails != 0;
}
